// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Which multi-tenancy model would you pick for this platform, and why?", "I would use a hybrid. Most schools share a database and a schema, and every table carries a tenant_id. Postgres row-level security enforces the tenant filter from a session variable that the gateway sets, so a missed WHERE clause in application code cannot leak rows across tenants. Large universities, or customers with contractual isolation or residency needs, get their own database, which a tenant routing table resolves. Shared schema keeps cost low and makes migrations simple across thousands of small schools. Dedicated databases limit the blast radius and noisy-neighbour risk for the big tenants. One codebase serves both models, because the data-access layer always resolves a connection from the tenant. Tests then confirm that no query can run without tenant context."),
    s(5, "How do you design offline attendance capture so that syncing never creates duplicates or loses marks?", "The mobile app writes each mark to local storage with a client-generated UUID. It also records the natural key (tenant, student, date, period), the teacher, the device time and a local sequence number. On sync it sends batches, and the server upserts on the natural key, storing the UUID so that a retried batch has no effect. When two devices submit the same period, I would not silently use last-write-wins. The rule is that the assigned teacher or a later explicit edit wins, and the server keeps the full history for audit. Late syncs still emit absence events, but the notification hub suppresses alerts once the school's cutoff has passed. Teachers see a sync status per class, so an unsynced register is visible instead of failing silently."),
    s(5, "Walk me through how a result moves from marks entry to publication without an unapproved result ever going out.", "Results move through a state machine: draft, submitted, moderated, approved, locked, published. Teachers can edit marks only while the result is in draft. Submitting freezes that section's sheet. Moderation applies scaling or rechecks and records every change with its reason. The HOD or exam controller then approves, and the system enforces maker-checker, so the approver cannot be the person who entered the marks. Approval creates an immutable, versioned snapshot together with a content hash. Publication is a separate, scheduled action that refers to a specific approved version. The portal reads only from published snapshots and never from working tables. The publish commit and its outbox event are written in one transaction. Every transition is audited, and the service rejects any skipped state."),
    s(5, "Result day brings a huge traffic spike. How do you keep the portal up?", "Results are read-heavy and immutable once published, so I precompute them. At publish time a job renders each student's result into a document or JSON blob in object storage, keyed by an unguessable token. The portal API checks authorisation, which is cheap because relationships are cached, and then returns the precomputed artefact or a short-lived signed URL. Nothing joins live marks tables. I would pre-scale the API tier and warm the caches ahead of the scheduled publish time. Tenants can also release results in staggered batches. Login, especially OTP, is often the real bottleneck, so I would raise SMS throughput in advance and keep existing sessions valid. Per-tenant rate limits stop one university's result day from affecting other tenants."),
    s(4, "How do you stop admissions from issuing more accepted offers than there are seats?", "Each programme or class has a seat inventory row that holds capacity, the number accepted and the number held. Accepting an offer runs one transaction. It checks that the offer is still valid and before its deadline, then increments the accepted count with a conditional update such as 'accepted < capacity'. A database constraint backs this up. If the update affects no rows, the applicant is waitlisted. Offers can deliberately exceed seats when a school expects some applicants to decline, but acceptances never can. When offers expire, a scheduled job releases the holds and moves to the next merit-list candidate. However, the acceptance transaction itself checks the deadline, so a late job never lets an expired offer through. The application fee and the acceptance fee use the normal ledger flow."),
    s(3, "Why use a stable internal student ID instead of APAAR or an enrolment number as the primary key?", "External identifiers are not under our control. A new applicant may not have an APAAR ID yet. Numbers get entered wrongly and corrected later. Universities reissue enrolment numbers after a transfer. Some students never get certain IDs at all. If one of these were the primary key, every correction would cascade through attendance, the ledger, results and events. A surrogate ID, such as a UUID or ULID generated by the SIS, never changes, and external IDs sit in an identifiers table with type, value, verification status and validity dates. Each type has a uniqueness constraint per tenant where that makes sense. Events and the reporting store carry the internal ID or a pseudonym of it, which also keeps government identifiers out of logs and analytics."),
    s(4, "Give a back-of-envelope estimate for attendance write load.", "I would state the assumptions first. Say 2,000 tenants average 1,000 students each, which is 2 million students, with 8 periods a day. That gives about 16 million attendance records a day. Most of them arrive in a window of roughly six school hours, which averages around 750 writes per second. Marks come in bursts at the start of each period, so I would plan for perhaps ten times the average and design for 10,000 records per second. Batching each class register into one request cuts the request rate by about 40 times. Records are small, a few hundred bytes, so storage per day is single-digit gigabytes. That fits Postgres partitioned by month and tenant. Absence events are a fraction of the writes and drive the notification load."),
    s(4, "How would you model the fee ledger?", "I would use double-entry accounting. A journal_entries table records the header: tenant, timestamp, source type and source ID, such as a webhook event, and an idempotency key with a unique constraint. A journal_lines table holds each account, debit or credit, amount in paise as an integer, and currency, and the lines of every entry must balance to zero. The accounts include student receivable, gateway clearing, bank, concession expense and late-fee income. Invoices are a separate table that links to receivable lines. An invoice's paid status is derived from what has been allocated against it, not stored as a flag that someone can edit. Entries are append-only, and a correction is a reversal plus a new entry. Gateway settlement reports move money from clearing to bank, and any reconciliation difference goes to a suspense account for a person to review."),
    s(4, "What does the notification hub need to handle beyond simply sending messages?", "First, it checks each guardian's channel preferences and recorded consent before sending anything. It also respects quiet hours, except for urgent safety alerts. Second, Indian regulatory constraints apply. Commercial SMS must use TRAI DLT-registered headers and templates, and WhatsApp business messages need approved templates and user opt-in. Third, delivery must be reliable. The hub uses a dedup key of event ID, recipient and channel, retries with backoff, and fails over to another channel or provider. It records delivery receipts. Fourth, it localises messages, because guardians prefer different languages. Fifth, it protects privacy by keeping sensitive details, such as marks, out of SMS bodies and sending a link that requires login. Finally, it applies per-tenant quotas and cost tracking, since SMS volume costs money."),
    s(3, "What can go wrong with the transactional outbox, and how do you handle it?", "The relay can crash after publishing a message but before marking the row as sent. That produces duplicates, so delivery is at-least-once and every consumer deduplicates on event ID. The relay can also fall behind, so I would alert on outbox lag and on the age of the oldest unsent row. Ordering matters for each student, so events are keyed by student or aggregate ID and the relay keeps commit order within a key. The outbox table grows without limit unless sent rows are purged or partitions are dropped. A CDC-based relay such as Debezium reads the outbox from the WAL, which avoids polling load. A poison event that a consumer keeps failing on goes to a dead-letter topic, and the consumer keeps processing other messages."),
    s(3, "How do you pseudonymise the reporting store without breaking analytics?", "I would replace direct identifiers such as name, phone, APAAR and Aadhaar-linked fields with a keyed hash, an HMAC with a secret for each tenant, applied during CDC. Joins across tables still work because the same input always gives the same pseudonym. Free text such as remarks is dropped. Quasi-identifiers such as date of birth, pincode and category are made coarser where dashboards do not need full detail. Dashboards suppress small cells, for example by hiding counts below a threshold, so nobody can single out a student. Pseudonymised data is still personal data under the DPDP Act, so access is role-based and logged. Statutory exports that need real identities are produced through a controlled job that re-identifies under authorisation. The key never sits in the warehouse."),
    s(4, "How does India's DPDP Act shape this system's design?", "The Digital Personal Data Protection Act 2023 treats anyone under 18 as a child. Processing a child's data needs verifiable consent from a parent or lawful guardian, and the Act bars tracking, behavioural monitoring and targeted advertising aimed at children. The 2025 rules allow certain exemptions for educational institutions, but I would confirm the current scope with counsel rather than assume. In the design, consent records carry the purpose, the version and the guardian's identity. The system collects only the data each purpose needs and applies retention schedules. It supports access, correction and erasure requests where law permits, and it has a breach-response runbook. Analytics never profile children for marketing. The platform acts as processor for the school, which is the data fiduciary, so contracts and audit logs must support that relationship."),
    s(4, "A court order removes one parent's access to a child. How quickly and reliably does the system enforce it?", "The guardian relationship is the source of truth in the SIS, and it has an effective-from date and a status. Revoking it commits the change and an outbox event in one transaction. The authorisation layer checks relationships at request time, using a cache keyed on user and student with a short TTL. The revocation event also invalidates that cache entry explicitly, so enforcement takes seconds rather than waiting for the TTL to expire. Active sessions and refresh tokens for that user are revoked for that student, and the system cancels pending notifications to the removed guardian. Sensitive changes like this require maker-checker approval and are audited. Previously sent documents cannot be recalled, so the school is warned that history is not retroactively hidden from the parent."),
    s(3, "Why apply timetable changes as substitutions rather than re-running the solver?", "Once a timetable is published, people depend on it. Students, teachers and room bookings are planned around it. A full re-solve can move hundreds of slots to fix one absence, and the solver's objective does not value stability unless you model that explicitly. A substitution is local. It finds a free, qualified teacher for that slot, checks hard rules such as clashes and maximum load, and records it as an overlay with a date range, so the base timetable stays the same. Notifications go only to the people affected. A re-solve makes sense at term boundaries or after structural changes. Even then I would add a penalty for each change compared with the current timetable, so the new solution stays close to the old one."),
    s(4, "How do you prevent noisy neighbours in a shared multi-tenant deployment?", "The gateway applies rate limits and concurrency quotas per tenant, with tiers by plan. Heavy work, such as bulk report generation, timetable solving, merit-list runs and statutory exports, goes to async job queues with fair scheduling per tenant, so one university's export cannot starve other tenants. Database protection comes from statement timeouts, separate read replicas for reporting queries, and the reporting store itself, which keeps analytics off the OLTP database. Metrics broken down by tenant show who is consuming resources. If one tenant keeps dominating, I would move them to a dedicated database or cell. Over time the deployment becomes cells, each holding a group of tenants, which limits the blast radius of any incident."),
    s(4, "A published result has an error. How do you correct it?", "The locked version is never edited. Someone raises a correction request with a reason, for example after revaluation or because of a data-entry error, and attaches the changed marks. The request goes through the same moderation and approval path, and the approver must be different from the requester. Approval creates version N+1 with a link to version N and a diff. Publishing the new version marks the old one as superseded, while keeping it in the audit trail. The portal shows the current version with a note that it was revised, and downloaded marksheets carry a version number and a verification QR code or hash. The system sends a results.corrected event, so guardians are notified and downstream systems, such as scholarship or promotion logic, recompute from the new version."),
    s(3, "How would you design audit logging for who viewed or changed student data?", "Every read of sensitive resources, such as health notes, marks and documents, and every write produces an audit record. The record holds the actor, their role and relationship, the tenant, the resource, the action, the purpose, time, IP address and request ID. Records go asynchronously to an append-only store. The services themselves cannot delete or alter it, because it uses WORM object storage or hash chaining, where each batch includes the previous batch's hash. Logs never contain the personal data itself, only references to it. Retention follows the policy and the law. Schools can query who accessed a child's record, and alerts catch anomalies, such as a staff account reading hundreds of profiles outside its sections."),
    s(3, "How do you build admission forms that every school can configure without code changes?", "Each form is a versioned JSON schema with field types, validation rules, conditional visibility and document requirements, plus a UI layout. An application stores the form version it was submitted against, so later edits never make old submissions invalid. Fields that drive business logic, such as category, date of birth for age eligibility and the marks used for merit, are mapped to canonical attributes so that merit rules and reports work across schools. Other answers go into a JSONB column. Merit lists are configurable formulas, evaluated in a sandbox and versioned, and they can be explained per applicant. Tenants can publish a new form version only after a validation preview, and published versions are immutable."),
    s(3, "How do you handle document uploads such as birth certificates and marksheets securely?", "The client asks for a presigned upload URL scoped to one object key, with limits on size and content type. The file goes straight to object storage, into a quarantine prefix. An event then triggers malware scanning and file-type verification, and optionally OCR. Only files that pass move to the clean prefix and become visible to staff. Files are encrypted at rest with tenant-scoped keys, and downloads go through short-lived signed URLs issued after an authorisation check. Each document is linked to the application and to a retention rule. Documents from rejected applicants are deleted after the retention period. Thumbnails or previews never go into public buckets, and every view is audited."),
    s(3, "How does the fee model support instalments, concessions, late fees and partial payments?", "Each fee plan is a versioned rule set that resolves, by class, category and optional components such as transport, into an invoice schedule of instalments with due dates. Concessions and scholarships are separate ledger entries, debiting concession expense and crediting the receivable, so the original fee stays visible. A scheduled job posts late fees according to the plan's rules, and a waiver is a reversal approved by an authorised role. A partial payment is allocated across open instalments using a deterministic rule, oldest due first, unless staff override it. Because the paid amount is derived from allocations, dues dashboards always agree with the ledger. Changing a plan mid-year affects only future instalments. Invoices already issued are corrected through adjustments."),
    s(3, "How do you support very different grading schemes, such as school grades and university CGPA?", "A grading scheme is a versioned configuration. It defines the assessment components and their weights, the mark-to-grade bands, grade points, rules for passing and grace marks, credit weighting and rounding. Each exam or course offering refers to a specific scheme version, so results are reproducible even after the rules change. Calculation runs in a pure, deterministic function that is unit-tested against reference examples the controller supplies. It stores the inputs and outputs together, and it records the scheme version in the result snapshot. Teachers enter raw marks against components, and grades are always derived. Universities add credit-based aggregation, backlogs and re-attempts as course attempts linked to the student and term."),
    s(3, "What backup and disaster recovery targets would you set per subsystem?", "I would set targets according to the cost of losing data. The fee ledger and results need an RPO near zero, which means synchronous replication within the region, point-in-time recovery and immutable backups that sit in a separate account to resist ransomware. Attendance can tolerate an RPO of minutes, because devices keep a local copy and can re-sync. The reporting store can be rebuilt from CDC or from snapshots. For RTO, the portal and payments should come back within an hour or so, while reporting can wait longer. Data residency in India constrains where the DR region can be. Restores are drilled regularly per tenant, because an untested backup is not a real backup. Per-tenant restore is a feature in its own right, because one school's accidental bulk delete should not require a platform-wide rollback."),
    s(2, "How would you onboard a new school that is migrating from spreadsheets or a legacy system?", "I would provide import templates and a staged pipeline. The pipeline uploads the data, validates it against canonical schemas, and shows the school an error report and a preview. Only then does it commit, in idempotent batches keyed by a source record ID, so the import can be re-run safely. Students, guardians and relationships are imported first, then historical fees as opening balances in the ledger rather than replayed transactions, and then past results as archived read-only records. Guardian contact numbers need verification and consent before the system sends notifications. The tenant stays in a sandbox mode until the school signs off, so test notifications never reach real parents."),
    s(3, "A teacher leaves mid-term. How do you make sure their access disappears and nothing breaks?", "Staff identity comes from the school's identity provider through SSO. SCIM provisioning, or an HR event, disables the account, and the gateway rejects their tokens. Short token lifetimes and session revocation close any remaining window. Section and subject assignments end on the leaving date. That date drives the teacher-of-section relationship, so attribute-based checks fail straight away even if a cached token survives. Records the teacher created, such as attendance, marks and remarks, keep the author reference for audit. Pending work, including unsubmitted mark sheets and substitutions, appears on an admin dashboard so it can be reassigned. Timetable slots trigger substitutions until a replacement teacher joins."),
    s(2, "How do you handle a student moving between sections or campuses within the same tenant?", "The student's identity and internal ID stay the same. What changes is the enrolment, which I model as an effective-dated record of student, section, term, valid from and valid to. A move closes the old enrolment and opens a new one. Attendance, marks and timetable lookups resolve the section that applies on the relevant date, so history is preserved correctly. Teachers of the old section lose access from the move date, apart from completing assessments for the period they taught, which is an explicit exception scoped by time. Fee differences between campuses produce ledger adjustments. Moving between separate tenants is a formal transfer, with an export, guardian consent, and APAAR serving as the portable record."),
    s(3, "Two people edit the same mark sheet at the same time. What happens?", "Each mark sheet, meaning one section and one assessment, carries a version number. Saves are conditional updates on that version, which is optimistic locking. If the version has changed, the save is rejected and the client shows the conflicting cells so the user can merge them. Pessimistic locking would hold locks across slow mobile sessions, so I would avoid it. Only the assigned teacher can edit, so true conflicts are rare. They come mostly from the same teacher on two devices, or from a co-teacher. Each cell edit is recorded in history. Once the sheet is submitted, it is frozen, and later changes go through moderation, which removes the risk of concurrent edits during approval."),
    s(2, "How would you test and validate the timetable solver?", "I would check the hard constraints independently of the solver. A separate, simple checker confirms there are no teacher, room or section clashes, that teacher availability and required periods per subject are respected, and that rooms suit the subject, such as labs. The checker runs on every draft before an admin sees it. I would use property-based tests with generated instances, and a regression suite built from real anonymised tenant datasets, tracking soft-constraint scores and solve time. For infeasible inputs, the solver should report which constraints conflict instead of timing out silently. Solves run as async jobs with time limits and return the best solution found so far, and admins can pin slots before re-solving."),
    s(2, "How do you evolve event schemas on Kafka without breaking consumers?", "I would use a schema registry with Avro or Protobuf and enforce backward compatibility, so new fields are optional with defaults, nobody removes or reuses fields, and types do not change incompatibly. Events carry an envelope with event ID, type, version, tenant, aggregate ID and occurred_at. For a breaking change I would publish a new event type or topic version, run the old and new in parallel, migrate consumers, and then retire the old one. Consumers ignore fields they do not know. Contract tests in CI check producers against the schemas that consumers expect. Payloads carry IDs rather than full personal data where possible, which also shrinks the privacy impact of a long-retention topic."),
    s(3, "What SLOs and alerts would you define for this platform?", "I would tie SLOs to user journeys. Examples are portal login and page success rate and latency, attendance sync success, the gap between the cutoff and the parent absence alert, the time from payment to receipt, and the result publish completing on schedule. Alerts would cover outbox and consumer lag, webhook verification failures, reconciliation mismatches, and receipts stuck in a pending state, plus notification delivery failure rates per provider and channel and authorisation denials that spike unexpectedly. I would also monitor invariants as well as uptime. Ledger entries that do not balance, a published result without an approved version, and cross-tenant query attempts that RLS blocks should each page someone immediately, because they signal a correctness or security bug."),
    s(3, "How do you partition Kafka topics and preserve ordering where it matters?", "Kafka guarantees order only within a partition, so I would choose keys by the aggregate whose order matters. Attendance and SIS events use the student ID as the key, so a student's enrolment change is never processed after a later attendance mark. Payment events use the invoice or payment ID. Keys combine the tenant and the ID, which spreads load while keeping order. I would avoid using the tenant alone as the key, because one big university would create a hot partition. I would size partition counts for peak throughput, with headroom for consumer parallelism. Consumers still check versions or timestamps, because retries and the outbox can deliver duplicates. Cross-aggregate ordering is not guaranteed, so workflows rely on state checks rather than on events arriving in order."),
  ],
  objective: [
    o(5, "In a shared-schema Postgres multi-tenant design, what best prevents a missing WHERE tenant_id clause from leaking data?", ["Prefixing table names per tenant","Row-level security policies driven by a session tenant variable","Encrypting the tenant_id column","Adding an index on tenant_id"], 1, "RLS enforces the tenant filter in the database for every query, so a bug in application code cannot bypass it."),
    o(5, "Which key makes offline attendance sync idempotent across retries?", ["Server receive timestamp","Device ID only","Natural key (tenant, student, date, period) with an upsert","Auto-increment row ID"], 2, "Upserting on the natural key means a repeated sync overwrites the same logical record instead of inserting a duplicate."),
    o(4, "How should acceptance be implemented to avoid overbooking seats?", ["Check the seat count in the UI before submitting","A conditional update such as 'accepted < capacity' inside the acceptance transaction","A nightly job that cancels excess acceptances","Caching the seat count in Redis with a TTL"], 1, "An atomic conditional update in the database serialises concurrent acceptances against the real count."),
    o(4, "In the double-entry fee ledger, what invariant must every journal entry satisfy?", ["Total debits equal total credits","Each entry has exactly one line","Credits always exceed debits","Amounts are stored as floats"], 0, "Double-entry requires each entry to balance, which makes errors and missing money detectable."),
    o(4, "How should an incorrectly posted fee payment be corrected?", ["Update the amount on the existing line","Delete the entry and repost it","Post a reversal entry, then a correct entry","Edit the receipt PDF"], 2, "Ledgers are append-only, and reversals keep a complete, auditable history."),
    o(4, "To keep each student's events in order on Kafka, what should the message key be?", ["A random UUID","The event type","The tenant ID alone","A tenant-qualified student ID"], 3, "Kafka orders messages within a partition, and keying by student sends all of a student's events to one partition without creating tenant-level hot spots."),
    o(5, "What is the minimum check before trusting a payment gateway webhook?", ["Verifying the HMAC signature with the shared secret","Checking that the request came over HTTPS","Checking that the amount is positive","Checking the User-Agent header"], 0, "Signature verification proves the gateway sent the payload and that nobody tampered with it."),
    o(3, "Which deduplication key suits the notification hub?", ["Message body hash only","Event ID + recipient + channel","Recipient phone number only","Send timestamp"], 1, "It suppresses repeated sends of the same event to the same person on the same channel, while still allowing different channels."),
    o(3, "In India, what must be in place before sending commercial or transactional SMS from the platform?", ["Nothing, if the parent provided the number","Only a GST registration","Registered sender headers and templates on TRAI's DLT platform","An Aadhaar link for each recipient"], 2, "TRAI's regulations require DLT registration of entities, headers and templates, and operators block unregistered messages."),
    o(4, "Under India's DPDP Act 2023, processing a 12-year-old student's personal data generally requires what?", ["The student's own click-through consent","No consent, because schools are exempt from the whole Act","Only an internal policy document","Verifiable consent of a parent or lawful guardian"], 3, "The Act treats people under 18 as children and requires verifiable parental consent, subject to notified exemptions."),
    o(3, "Which statement about the pseudonymised reporting store is correct?", ["It is anonymous, so privacy law no longer applies","It is still personal data, and access must be controlled and logged","It can be shared publicly","It needs no retention policy"], 1, "Pseudonymised data can be re-identified with the key or with other data, so it remains personal data."),
    o(3, "Which is a hard constraint in timetable generation?", ["A teacher cannot be scheduled in two places in the same period","Teachers prefer free first periods","Heavy subjects should be in the morning","Minimise gaps between a teacher's classes"], 0, "A teacher clash makes the timetable infeasible, while the other options are preferences scored as soft constraints."),
    o(3, "A teacher is on leave tomorrow. What should the system do to the published timetable?", ["Re-solve the whole timetable","Unpublish the timetable","Apply a dated substitution overlay for the affected slots","Cancel the classes automatically"], 2, "Substitutions are local and keep the published base timetable stable."),
    o(5, "A locked, published result needs a correction. What is the correct approach?", ["Edit the locked marks directly as an admin","Create a new version that goes through approval and supersedes the old one","Delete the result and re-enter it","Fix it only in the reporting store"], 1, "Locked versions are immutable, so corrections need a new approved version with an audit link to the previous one."),
    o(4, "An outbox relay gives what delivery guarantee to consumers?", ["Exactly-once by default","At-most-once","No ordering at all","At-least-once, so consumers must be idempotent"], 3, "The relay can publish and then crash before marking the row sent, which causes redelivery."),
    o(3, "Why is APAAR stored as an attribute rather than as the primary key?", ["It may be missing, entered wrongly or corrected later","It is always longer than 64 characters","Databases cannot index strings","It changes every academic year"], 0, "External IDs are outside the platform's control, and a stable surrogate key avoids cascading updates."),
    o(4, "What is the best way to serve results on result day?", ["Join the live marks tables for each request","Email all results instead of using the portal","Serve precomputed per-student results after an authorisation check","Disable authentication to reduce load"], 2, "Published results are immutable, so precomputing removes expensive queries while access control stays in place."),
    o(4, "A guardian's access is revoked. What makes enforcement near-immediate?", ["Waiting for the access token to expire after 30 days","Checking relationships at request time and invalidating the cache through a revocation event","Asking the parent to log out","A nightly batch job"], 1, "Request-time checks combined with event-driven cache invalidation close the access window within seconds."),
    o(3, "Which control most directly protects parent OTP login against brute force?", ["Longer SMS text","Sending the OTP by email as well","Allowing unlimited attempts","Short OTP expiry plus per-number and per-IP attempt limits"], 3, "Short validity and attempt limits make guessing the OTP infeasible."),
    o(4, "A user paid, but no webhook has arrived after several minutes. What should the system do?", ["Mark the invoice paid based on the redirect URL","Ask the user to pay again","Keep the payment pending and confirm it through the gateway's status API or reconciliation","Cancel the order immediately"], 2, "Only verified server-side confirmation should post to the ledger, and polling or reconciliation covers lost webhooks."),
    o(3, "Which technique handles two devices saving the same mark sheet at once?", ["Optimistic locking with a version number","Last write wins silently","Table-level locks held during editing","Disabling mobile entry"], 0, "A conditional update on the version detects the conflict without holding locks during long sessions."),
    o(3, "The expiry job runs late, and an applicant accepts after the deadline. How do you prevent a wrong acceptance?", ["Run the expiry job more often","The acceptance transaction itself checks the offer deadline","Rely on the applicant's device clock","Allow it and fix it manually"], 1, "The authoritative check must happen at the point of acceptance and must not depend on a background job's timing."),
    o(2, "Which tool commonly streams Postgres changes from the WAL into Kafka for the reporting store?", ["Logstash","Airflow","Redis Streams","Debezium"], 3, "Debezium is a log-based CDC connector that reads the Postgres WAL through logical decoding."),
    o(3, "Which standard automates provisioning and deprovisioning staff accounts from a school's identity provider?", ["SCIM","SMTP","OAuth device flow","LDAP referrals"], 0, "SCIM is the standard protocol for syncing user lifecycle changes, such as disabling a user, from an IdP."),
    o(3, "Which upload flow is safest for admission documents?", ["Upload to a public bucket and share the link","Base64 in the form submission stored in the database","Presigned upload to quarantine, malware scan, then move to private storage","Email documents to the admissions office"], 2, "It limits the scope of the upload, blocks malicious files, and keeps documents private behind authorised access."),
    o(4, "Assume 2,000 tenants with 1,000 students each and 8 attendance periods a day. Roughly how many attendance records are written per day?", ["16 million","1.6 million","160 million","16 thousand"], 0, "2,000 × 1,000 = 2 million students, and 2 million × 8 periods = 16 million records."),
    o(3, "What makes an audit log tamper-evident?", ["Storing it in the same table as the data","Gzip compression","Hash-chaining batches or storing them on WORM object storage","Letting admins edit entries"], 2, "Chained hashes or write-once storage expose any alteration or deletion."),
    o(2, "Which change to an event schema is backward compatible?", ["Renaming a field","Adding an optional field with a default","Changing a field from string to integer","Removing a required field"], 1, "Existing consumers can ignore the new optional field, and old messages still deserialise correctly."),
    o(3, "A dashboard shows that 2 students in a small category failed. What privacy control applies?", ["Show names to help follow-up","Round the count up to 10","Export the data to a spreadsheet","Small-cell suppression, hiding counts below a threshold"], 3, "Very small counts can identify individuals, so suppression prevents re-identification."),
    o(4, "One university's bulk export slows every other tenant. Which mitigation fits best?", ["Per-tenant quotas and fair-scheduled async job queues","Bigger instances for everyone","Disabling exports","Asking the tenant to export at night"], 0, "Per-tenant limits and fair queuing stop one tenant from consuming shared capacity."),
  ],
};
export default bank;
